WITH filtered AS (SELECT id, order_id, shipped_date, delivered_date, cost, status, DATE_FORMAT(delivered_date, 'yyyy-MM') delivered_date_label FROM shipments WHERE shipped_date > DATE '2023-11-10' AND order_id IS NOT NULL) SELECT status, COUNT(*) AS event_count, SORT_ARRAY(COLLECT_SET(status)) AS status_list, SUM(CASE WHEN status = 'IN_TRANSIT' THEN cost ELSE 0 END) AS in_transit_cost, COUNT_IF(status = 'RETURNED') AS returned_events, APPROX_PERCENTILE(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, GROUPING_ID() AS grouping_id FROM filtered GROUP BY CUBE (status) HAVING event_count < 1;
